// Generated by scripts/extract-pink-sheet.ts. Re-run it to move to a newer month.
import pinkSheet from "./pink-sheet.json";

export type PriceSeriesId = keyof typeof pinkSheet.series;

export interface PriceSeries {
  column: string;
  unit: "$/mt" | "$/kg";
  value: number;
  description: string;
}

export const priceSource = {
  ...pinkSheet.source,
  period: pinkSheet.period,
};

export function priceSeries(id: PriceSeriesId): PriceSeries {
  return pinkSheet.series[id] as PriceSeries;
}

/** The World Bank monthly average for the extract's period, in US dollars per metric tonne. */
export function usdPerTonne(id: PriceSeriesId): number {
  const { unit, value } = priceSeries(id);
  return unit === "$/kg" ? Math.round(value * 1000 * 100) / 100 : value;
}
